head.script:
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.keyIsurCd, scwin.keyGubun;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        gform.scroll = "no";
        const arrPar = new Array();
        const prt = $c.frame.path("../");
        if (prt !== undefined) {
            scwin.fn_GetPar = prt.scwin.fn_GetPar;
            scwin.fn_SetPar = prt.scwin.fn_SetPar;
        }
        if (scwin.fn_GetPar !== undefined) {
            scwin.fn_GetPar(arrPar, dts_selectleadcom);
            scwin.keyIsurCd = (arrPar.length >= 1 ? arrPar[0] : "");
            scwin.keyGubun = (arrPar.length >= 2 ? arrPar[1] : "");

            // elw 종목 조회 보내기
            await scwin.setCode();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08045.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_leadcom_OnDblClick
 * @description grd_leadcom 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_leadcom_OnDblClick = function(row, colid) {
    try {
        scwin.add();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08045.grd_leadcom_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_selectleadcom_OnDblClick
 * @description grd_selectleadcom 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_selectleadcom_OnDblClick = function(row, colid) {
    try {
        scwin.del();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08045.grd_selectleadcom_OnDblClick" });
    }
};

